					}
				}
				zs, _ := d.Poles()
				unm := 0
				var bad []complex128
				for _, z := range zs {
					if !poleOnOrOutsideStabilityBoundary(z, false, poleStabilityTolerance(z)) {
						continue
					}
					ok := false
					for _, w := range want {
						if cmplx.Abs(z-w) < 0.25*cmplx.Abs(w) {
