# Candidate DCGain per channel. Usage: cand.py rows.jsonl out.jsonl
# Pole test tau = nr*eps*sigma_1 is the CANDIDATE's test, not SLICOT behaviour.
# TB04 variant zero test deg*eps*max|coef| is a second candidate test, also not SLICOT's.
import json, sys, time, warnings, numpy as np, ctrlsys
warnings.simplefilter('ignore')
EPS = 2.0**-52
F = lambda a: np.array(a, dtype=float, order='F')

def inf_sign(Ar, br, cr, x0, floor):
    # 1) simple pole: residue r=(c v)(w'b)/(w'v) from the smallest singular pair of x0 I-Ar;
    #    G(x0+h)~r/h for h>0, the oracle's direction; sub-noise r -> unknown.
    # 2) otherwise (cluster, w'v~0): sign of G(x0+h) at 3 decades of h, starting where the
    #    shifted matrix is solvable (smin>=1e3*nr*eps*s1); disagreement -> unknown.
    nr = len(Ar); P = x0*np.eye(nr)-Ar
    U, sv, Vt = np.linalg.svd(P)
    tau = nr*EPS*sv[0]
    w, v = U[:, -1], Vt[-1, :]; wv = float(w@v)
    simple = nr == 1 or sv[-2] > tau
    if simple and abs(wv) > 1e3*nr*EPS:
        a, b = float((cr@v).item()), float((w@br).item())
        r = a*b/wv
        return 0 if abs(a*b) <= nr*EPS*np.linalg.norm(cr)*np.linalg.norm(br) or r == 0 else int(np.sign(r))
    h = floor
    for _ in range(60):
        M = (x0+h)*np.eye(nr)-Ar
        if not np.all(np.isfinite(M)): return 0
        s = np.linalg.svd(M, compute_uv=False)
        if s[-1] >= 1e3*nr*EPS*s[0]: break
        h *= 10.
    else: return 0
    sg = []
    for k in (1., 10., 100.):
        M = (x0+k*h)*np.eye(nr)-Ar
        g = (cr@np.linalg.solve(M, br)).item()
        if not np.isfinite(g) or g == 0: return 0
        sg.append(np.sign(g))
    return int(sg[0]) if sg[0] == sg[1] == sg[2] else 0

def tb01(A, b, c, Dij, x0, eq):
    r = dict(nr=None, i1=None, i5=None, smin=None, s1=None, k='err', v=None, sign=0)
    try:
        a, br, cr, nr, _, i1 = ctrlsys.tb01pd('M', eq, A.copy(order='F'), b.copy(order='F'), c.copy(order='F'), 0.0)
        r.update(nr=int(nr), i1=int(i1))
        if i1 != 0: r['k'] = 'info'; return r
        if nr == 0: r.update(k='val', v=Dij); return r
        a = F(a[:nr, :nr]); br = F(br[:nr, :1]); cr = F(cr[:1, :nr])
        sv = np.linalg.svd(x0*np.eye(nr)-a, compute_uv=False)
        r.update(smin=float(sv[-1]), s1=float(sv[0]))
        tau = nr*EPS*sv[0]
        if sv[-1] <= tau:
            r.update(k='inf', sign=inf_sign(a, br, cr, x0, max(sv[-1], tau) or EPS)); return r
        g, _, _, _, _, i5 = ctrlsys.tb05ad('N', 'G', a.copy(order='F'), br.copy(order='F'), cr.copy(order='F'), complex(x0))
        r['i5'] = int(i5)
        if i5 != 0: r['k'] = 'info'; return r
        r.update(k='val', v=float(g.ravel()[0].real)+Dij)
    except Exception as e:
        r['e'] = repr(e)[:120]
    return r

def deflate(p, x0):
    # order of the root at x0 under |rem|<=deg*eps*max|coef|, and the deflated polynomial
    p = np.array(p, float); o = 0
    while len(p) > 1:
        q, rem = np.zeros(len(p)-1), p[0]
        for i in range(1, len(p)):
            q[i-1] = rem; rem = rem*x0+p[i]
        if abs(rem) > (len(p)-1)*EPS*np.abs(p).max(): break
        p = q; o += 1
    return o, p

def tb04(A, b, c, Dij, x0):
    r = dict(nr=None, i1=None, k='err', v=None, sign=0)
    try:
        out = ctrlsys.tb04ad('R', A.copy(order='F'), b.copy(order='F'), c.copy(order='F'), F([[Dij]]), 0.0, 0.0)
        nr, idx, dc, uc, i1 = out[4], out[5], out[6], out[7], out[8]
        r.update(nr=int(nr), i1=int(i1))
        if i1 != 0: r['k'] = 'info'; return r
        deg = int(idx[0]); d = dc[0, :deg+1]; u = uc[0, 0, :deg+1]
        r['den0'] = float(np.polyval(d, x0))
        od, dp = deflate(d, x0); on, up = deflate(u, x0)
        if np.all(u == 0): r.update(k='val', v=0.0); return r
        dv, nv = np.polyval(dp, x0), np.polyval(up, x0)
        if on < od: r.update(k='inf', sign=int(np.sign(nv*dv)))
        elif on > od: r.update(k='val', v=0.0)
        else: r.update(k='val', v=float(nv/dv))
    except Exception as e:
        r['e'] = repr(e)[:120]
    return r

def main(src, dst):
    T = dict(N=0., S=0., T=0.); nrows = 0
    with open(src) as f, open(dst, 'w') as o:
        for line in f:
            R = json.loads(line); nrows += 1
            n, m, p = R['n'], R['m'], R['p']; x0 = 1. if R['dt'] > 0 else 0.
            arr = lambda k, s: F([float(x) for x in R[k]]).reshape(s)
            A, B, C, D = arr('A', (n, n)), arr('B', (n, m)), arr('C', (p, n)), arr('D', (p, m))
            for i in range(p):
                for j in range(m):
                    b, c, d = F(B[:, [j]]), F(C[[i], :]), float(D[i, j])
                    out = dict(family=R['family'], id=R['id'], i=i, j=j)
                    for eq in 'NS':
                        t = time.perf_counter(); out[eq] = tb01(A, b, c, d, x0, eq); T[eq] += time.perf_counter()-t
                    t = time.perf_counter(); out['T'] = tb04(A, b, c, d, x0); T['T'] += time.perf_counter()-t
                    o.write(json.dumps(out)+'\n')
    print('rows', nrows, 'us/model', {k: round(1e6*v/nrows, 1) for k, v in T.items()})
main(sys.argv[1], sys.argv[2])
