# Usage: tally.py rows.jsonl channels.jsonl outdir  -> tables.txt, listed.txt, disagree.txt
import json, sys, math
from collections import defaultdict
fl = float
src, ch, out = sys.argv[1:4]
ORDER = ['listed','named','series1','series1lag','series2','series3','dseries','dover-pcg','dover-grid','dpar','dpar0','x-d2-pcg','x-dplant-pcg','scaling',
 'F1intBesideRegular','F2tinyBlockInt','F3denseExactSingular','F4nearDCTriangle','F5illCondBlockBesideStiff','F6residueCancelExact','F6residueCancelRounded','F7tfTrailingZeroDen','F8rotatedIntegrator','F9extremeScale','pipeInf','pipeFinite']
COLS = ['correct','falseCancel','falsePole','wrongFinite','info','signWrong','signUnk','err']
def cat(ref, k, v, s):
    """ref: float or 'Inf'/'finite' class. cand: k in val/inf/info/err"""
    if k == 'info': return 'info'
    if k == 'err': return 'err'
    if ref == 'Inf': return 'correct' if k == 'inf' else 'falseCancel'
    if ref == 'finite': return 'correct' if k == 'val' else 'falsePole'
    if math.isinf(ref):
        if k == 'val': return 'falseCancel'
        if s == 0: return 'signUnk'
        return 'correct' if s == math.copysign(1, ref) else 'signWrong'
    if k == 'inf': return 'falsePole'
    if math.isnan(v): return 'wrongFinite'
    if math.isinf(v): return 'falsePole'
    ok = abs(v) <= 1e-6 if ref == 0 else abs(v-ref) <= 1e-6*abs(ref)
    return 'correct' if ok else 'wrongFinite'
rows = {}
for l in open(src):
    r = json.loads(l); rows[(r['family'], r['id'])] = r
chans = defaultdict(list)
for l in open(ch):
    c = json.loads(l); chans[(c['family'], c['id'])].append(c)
def refval(r, which, q):
    if which == 'intended':
        if 'intended' in r: return fl(r['intended'][q])
        return r.get('intended_kind') or None
    if which == 'oracle': return fl(r['oracle'][q])
    if which == 'main':
        return fl(r['main'][q]) if 'main' in r else None
def mainc(r, q):
    if 'main' not in r: return ('err', None, 0)
    v = fl(r['main'][q])
    if math.isinf(v): return ('inf', None, int(math.copysign(1, v)))
    return ('val', v, 0)
def table(name, cand, which):
    T = defaultdict(lambda: defaultdict(int))
    for key, r in rows.items():
        allok = True; any_ = False
        for c in chans[key]:
            q = c['i']*r['m']+c['j']; ref = refval(r, which, q)
            if ref is None: continue
            k, v, s = cand(r, c, q); x = cat(ref, k, v, s); T[r['family']][x] += 1; T[r['family']]['n'] += 1
            any_ = True; allok = allok and x == 'correct'
        if any_:
            T[r['family']]['rows'] += 1; T[r['family']]['rowsOK'] += allok
    L = [f'## {name} vs {which}', f"{'family':28}{'entries':>8}" + ''.join(f'{x:>12}' for x in COLS) + f"{'rowsOK/rows':>14}"]
    for f in ORDER:
        if f in T:
            t = T[f]
            L.append(f"{f:28}{t['n']:>8}" + ''.join(f'{t[x]:>12}' for x in COLS) + f"{str(t['rowsOK'])+'/'+str(t['rows']):>14}")
    return '\n'.join(L)
def var(e):
    return lambda r, c, q: (c[e]['k'], c[e]['v'], c[e].get('sign', 0))
main = lambda r, c, q: mainc(r, q)
with open(out+'/tables.txt', 'w') as o:
    o.write('Category rule: reference finite nonzero rel 1e-6; reference 0 abs 1e-6; entries per channel; pipeline intended is class only (no sign).\n\n')
    for w in ('intended', 'oracle'):
        o.write(table('MAIN (current DCGain)', main, w)+'\n\n')
    for e, nm in (('N', 'CANDIDATE TB01PD equil N'), ('S', 'CANDIDATE TB01PD equil S'), ('T', 'VARIANT TB04AD')):
        for w in ('intended', 'oracle', 'main'):
            o.write(table(nm, var(e), w)+'\n\n')
with open(out+'/listed.txt', 'w') as o:
    fm = lambda c: {'val': (lambda: f"{c['v']:.6g}"), 'inf': (lambda: {1: '+Inf', -1: '-Inf', 0: '?Inf'}[c['sign']]), 'info': (lambda: f"info{c.get('i1')}/{c.get('i5')}"), 'err': (lambda: 'err')}[c['k']]()
    for key, r in rows.items():
        if r['family'] not in ('listed', 'named'): continue
        for c in chans[key]:
            q = c['i']*r['m']+c['j']
            it = r['intended'][q] if 'intended' in r else '-'
            o.write(f"{r['id']:18}({c['i']},{c['j']}) intended={it} oracle={fl(r['oracle'][q]):.6g} main={r['main'][q] if 'main' in r else 'ERR'} | N {fm(c['N'])} nr={c['N']['nr']} | S {fm(c['S'])} nr={c['S']['nr']} | T {fm(c['T'])} nr={c['T']['nr']}\n")
D = defaultdict(list)
for key, r in rows.items():
    for q in range(r['p']*r['m']):
        i = refval(r, 'intended', q)
        if i is None: continue
        w = fl(r['oracle'][q])
        if isinstance(i, str):
            bad = (i == 'Inf') != math.isinf(w)
        elif math.isinf(i) or math.isinf(w):
            bad = i != w
        else:
            bad = not (abs(w) <= 1e-6 if i == 0 else abs(w-i) <= 1e-6*abs(i))
        if bad: D[r['family']].append(f"{r['id']}[{q}] intended={i} oracle={w:.17g}")
with open(out+'/disagree.txt', 'w') as o:
    for f in ORDER:
        o.write(f"# {f}: {len(D[f])}\n"); o.writelines(x+'\n' for x in D[f])
print({f: len(D[f]) for f in ORDER})
