package controlsys

import (
	"bufio"
	"encoding/json"
	"fmt"
	"math"
	"math/rand/v2"
	"os"
	"testing"
)

type xRow struct {
	Family   string   `json:"family"`
	ID       string   `json:"id"`
	N        int      `json:"n"`
	M        int      `json:"m"`
	P        int      `json:"p"`
	Dt       float64  `json:"dt"`
	A        []string `json:"A"`
	B        []string `json:"B"`
	C        []string `json:"C"`
	D        []string `json:"D"`
	Intended []string `json:"intended,omitempty"`
	Kind     string   `json:"intended_kind,omitempty"`
	Oracle   []string `json:"oracle"`
	Main     []string `json:"main,omitempty"`
	MainErr  string   `json:"main_err,omitempty"`
	NewErr   string   `json:"new_err,omitempty"`
	OracleX  string   `json:"oracle_xcheck,omitempty"`
}

func xs(v []float64) []string {
	o := make([]string, len(v))
	for i, x := range v {
		o[i] = fmt.Sprintf("%.17g", x)
	}
	return o
}

type xW struct {
	e *json.Encoder
	c map[string]int
}

func (w xW) raw(fam, id string, n, m, p int, a, b, c, d []float64, dt float64, intended []float64, kind string) {
	x0 := 0.0
	if dt > 0 {
		x0 = 1
	}
	r := xRow{Family: fam, ID: id, N: n, M: m, P: p, Dt: dt, A: xs(a), B: xs(b), C: xs(c), D: xs(d), Kind: kind}
	if intended != nil {
		r.Intended = xs(intended)
	}
	r.Oracle = xs(dcrLimit(n, m, p, a, b, c, d, x0))
	if sys, err := NewFromSlices(n, m, p, a, b, c, d, dt); err != nil {
		r.NewErr = err.Error()
	} else if g, err := sys.DCGain(); err != nil {
		r.MainErr = err.Error()
	} else {
		r.Main = xs(g.RawMatrix().Data)
	}
	if err := w.e.Encode(r); err != nil {
		panic(err)
	}
	w.c[fam]++
}

func (w xW) sys(fam, id string, s *System, intended []float64, kind string) {
	n, m, p := s.Dims()
	w.raw(fam, id, n, m, p, s.A.RawMatrix().Data, s.B.RawMatrix().Data, s.C.RawMatrix().Data, s.D.RawMatrix().Data, s.Dt, intended, kind)
}

func (w xW) listed(t *testing.T, fam, id string, n, m, p int, a, b, c, d []float64, dt float64, intended []float64) {
	x0 := 0.0
	if dt > 0 {
		x0 = 1
	}
	o1, o2 := dcrLimit(n, m, p, a, b, c, d, x0), rowsLimit(n, m, p, a, b, c, d, x0)
	for i := range o1 {
		if o1[i] != o2[i] && math.Abs(o1[i]-o2[i]) > 1e-12*math.Abs(o1[i]) {
			t.Errorf("oracle mismatch %s %d: %v %v", id, i, o1[i], o2[i])
		}
	}
	w.raw(fam, id, n, m, p, a, b, c, d, dt, intended, "")
}

func rowsLimit(n, m, p int, a, b, c, d []float64, x0 float64) []float64 {
	den, at := fzCharPolyExact(a, n), fzRat(x0)
	out := make([]float64, p*m)
	bj := make([]float64, n)
	for i := range p {
		for j := range m {
			for k := range n {
				bj[k] = b[k*m+j]
			}
			num := fzPencilDetRat(n, 1, a, bj, c[i*n:(i+1)*n], []float64{d[i*m+j]})
			out[i*m+j] = fzLimitAt(num, den, at)
		}
	}
	return out
}

