// fzNewtonRoot refines z on the exact descending polynomial c by 400-bit
// complex Newton iteration.
func fzNewtonRoot(c []*big.Rat, z complex128) complex128 {
	const prec = 400
	nf := func() *big.Float { return new(big.Float).SetPrec(prec) }
	mul := func(ar, ai, br, bi *big.Float) (*big.Float, *big.Float) {
		return nf().Sub(nf().Mul(ar, br), nf().Mul(ai, bi)), nf().Add(nf().Mul(ar, bi), nf().Mul(ai, br))
	}
	cf := make([]*big.Float, len(c))
	for i, v := range c {
		cf[i] = nf().SetRat(v)
	}
	zr, zi := nf().SetFloat64(real(z)), nf().SetFloat64(imag(z))
	for range 200 {
		pr, pi, dr, di := nf(), nf(), nf(), nf()
		for _, v := range cf {
			dr, di = mul(dr, di, zr, zi)
			dr.Add(dr, pr)
			di.Add(di, pi)
			pr, pi = mul(pr, pi, zr, zi)
			pr.Add(pr, v)
		}
		den := nf().Add(nf().Mul(dr, dr), nf().Mul(di, di))
		if den.Sign() == 0 {
			break
		}
		sr, si := mul(pr, pi, dr, nf().Neg(di))
		sr.Quo(sr, den)
		si.Quo(si, den)
		zr.Sub(zr, sr)
		zi.Sub(zi, si)
		step, _ := nf().Add(nf().Mul(sr, sr), nf().Mul(si, si)).Float64()
		size, _ := nf().Add(nf().Mul(zr, zr), nf().Mul(zi, zi)).Float64()
		if step <= 1e-90*size {
			break
		}
	}
	re, _ := zr.Float64()
	im, _ := zi.Float64()
	return complex(re, im)
}
