	Seed                       uint64
	N, P                       int
	Skip                       string
	Routed                     bool
	ErrC2D, ErrFit, ErrDelayed float64
	TwinFitPen, TwinDelayed    float64
	FitRMS, FitMax             float64
	StableBranch, StableTwin   bool
}

func lspErr(t *testing.T, d *System, pen *System, dt float64, p int) float64 {
	w := 0.0
	for q := 1; q < 200; q++ {
		th := math.Pi * float64(q) / 200
		g, err := d.EvalFr(cmplx.Exp(complex(0, th)))
		if err != nil {
			return 1e300
		}
		want := pencilResponse(t, pen, complex(0, th/dt))
		for i := range p {
			w = math.Max(w, cmplx.Abs(g[i][0]-want[i][0])/math.Max(1, cmplx.Abs(want[i][0])))
		}
	}
	if math.IsNaN(w) {
		return 1e300
	}
	return w
}

