func lspDump(f *os.File, label string, s *System, err error) {
	if err != nil {
		fmt.Fprintf(f, "%s err %v\n", label, err)
		return
	}
	for _, m := range []*mat.Dense{s.A, s.B, s.C, s.D, s.E} {
		if m == nil {
			fmt.Fprint(f, "nil;")
			continue
		}
		r, c := m.Dims()
		for i := range r {
			for j := range c {
				fmt.Fprintf(f, "%x,", m.At(i, j))
			}
		}
		fmt.Fprint(f, ";")
	}
	fmt.Fprintf(f, " %s %v %v %v\n", label, s.InputDelay, s.OutputDelay, s.Dt)
	_ = label
}

