func rv4Model(seed uint64) (*System, string) {
	rng := rand.New(rand.NewPCG(seed, 5277))
	kind := rng.IntN(9)
	n := 2 + rng.IntN(7)
	m, p := 1, 1
	if rng.IntN(2) == 0 {
		m, p = 1+rng.IntN(3), 1+rng.IntN(3)
	}
	disc := rng.IntN(2) == 0
	dt := 0.0
	if disc {
		dt = []float64{1, 0.1, 0.01, 1e-3}[rng.IntN(4)]
	}
	A := mat.NewDense(n, n, nil)
	B := mat.NewDense(n, m, nil)
	C := mat.NewDense(p, n, nil)
	D := mat.NewDense(p, m, nil)
	fillBC := func() {
		for r := range n {
			for c := range m {
				B.Set(r, c, rng.NormFloat64())
			}
			for c := range p {
				C.Set(c, r, rng.NormFloat64())
			}
		}
	}
	// diagonal-ish modal block with given continuous eigenvalues
	modal := func(cont []complex128) *mat.Dense {
		blk := mat.NewDense(n, n, nil)
		i := 0
		for _, q := range cont {
			if i >= n {
				break
			}
			if imag(q) > 0 && i+1 < n {
				e := q
				if disc {
					e = cmplx.Exp(q * complex(dt, 0))
				}
				blk.Set(i, i, real(e))
				blk.Set(i, i+1, imag(e))
				blk.Set(i+1, i, -imag(e))
				blk.Set(i+1, i+1, real(e))
				i += 2
				continue
			}
			e := real(q)
			if disc {
				e = math.Exp(real(q) * dt)
			}
			blk.Set(i, i, e)
			i++
		}
		for ; i < n; i++ {
			e := -1.0
			if disc {
				e = math.Exp(-dt)
			}
			blk.Set(i, i, e)
		}
		return blk
	}
	randCont := func() []complex128 {
		var out []complex128
		for len(out) < n {
			if rng.IntN(2) == 0 {
				out = append(out, complex(-0.05-2*rng.Float64(), 0.1+2*rng.Float64()), 0)
			} else {
				out = append(out, complex(-0.05-2*rng.Float64(), 0))
			}
		}
		return out
	}
	fillBC()
	switch kind {
	case 0: // dense random
		for r := range n {
			for c := range n {
				A.Set(r, c, rng.NormFloat64()/math.Sqrt(float64(n)))
			}
		}
		if disc {
			A.Scale(0.6, A)
		} else {
			for r := range n {
				A.Set(r, r, A.At(r, r)-1.5)
			}
		}
	case 1: // block diagonal; input j drives only block j
		blk := modal(randCont())
		cut := 1 + rng.IntN(n-1)
		A.Copy(blk)
		for r := range n {
			for c := range m {
				if (r < cut) != (c%2 == 0) {
					B.Set(r, c, 0)
				}
			}
		}
		if rng.IntN(2) == 0 {
			T, Ti, ok := rv4Rot(rng, n, 0.3)
			if !ok {
