			}
			A = rv4Sim(T, A, Ti)
			var b, c mat.Dense
			b.Mul(T, B)
			c.Mul(C, Ti)
			B, C = &b, &c
		}
	case 2: // genuinely non-minimal: uncontrollable last mode, rotated
		blk := modal(randCont())
		for r := range n {
			for c := r + 1; c < n; c++ {
				blk.Set(r, c, blk.At(r, c)+0.3*rng.NormFloat64())
			}
		}
		for r := 1; r < n; r++ {
			for c := 0; c < r; c++ {
				if !(blk.At(r, c) != 0 && blk.At(c, r) != 0) {
					blk.Set(r, c, 0)
				}
			}
		}
		// keep complex blocks intact; zero B row of last real state
		last := n - 1
		if last > 0 && blk.At(last, last-1) != 0 {
			for c := range m {
				B.Set(last-1, c, 0)
			}
			for c := 0; c < last-1; c++ {
				blk.Set(last-1, c, 0)
				blk.Set(last, c, 0)
			}
		} else {
			for c := 0; c < last; c++ {
				blk.Set(last, c, 0)
			}
		}
		for c := range m {
			B.Set(last, c, 0)
		}
		T, Ti, ok := rv4Rot(rng, n, 0.3)
