		delta := []float64{1e-4, 1e-6, 1e-8, 1e-10}[rng.IntN(4)]
		if blk.At(1, 0) == 0 && blk.At(0, 1) == 0 {
			blk.Set(1, 1, blk.At(0, 0)*(1+delta))
