				A.Set(r, r, lam)
				if r+1 < k {
					A.Set(r, r+1, 1)
				}
			} else if disc {
				A.Set(r, r, 0.9*rng.Float64())
			} else {
				A.Set(r, r, -0.2-2*rng.Float64())
			}
		}
		T, Ti, ok := rv4Rot(rng, n, 0.3)
		if !ok {
			return nil, "sing"
		}
		A = rv4Sim(T, A, Ti)
		var b, c mat.Dense
		b.Mul(T, B)
		c.Mul(C, Ti)
		B, C = &b, &c
	case 6: // deadbeat / FIR (nilpotent), optionally rotated
		disc = true
