			if !ok {
				return nil, "sing"
			}
			A = rv4Sim(T, A, Ti)
			var b, c mat.Dense
			b.Mul(T, B)
			c.Mul(C, Ti)
			B, C = &b, &c
		}
	case 7: // integrators / pole at z=1, with D
		blk := modal(randCont())
		blk.Set(0, 0, 0)
		if disc {
			blk.Set(0, 0, 1)
		}
		if blk.At(0, 1) != 0 {
			blk.Set(0, 1, 0)
			blk.Set(1, 0, 0)
		}
		for r := range n {
			for c := r + 1; c < n; c++ {
				if blk.At(r, c) == 0 && blk.At(c, r) == 0 {
					blk.Set(r, c, 0.5*rng.NormFloat64())
				}
			}
		}
		A.Copy(blk)
		for r := range p {
			for c := range m {
				D.Set(r, c, rng.NormFloat64())
			}
		}
	case 8: // structurally decoupled states (Sminreal path)
		for r := range n {
			for c := range n {
				A.Set(r, c, rng.NormFloat64()/math.Sqrt(float64(n)))
				if c < r && rng.IntN(2) == 0 {
					A.Set(r, c, 0)
				}
			}
		}
		if disc {
			A.Scale(0.5, A)
		} else {
			for r := range n {
				A.Set(r, r, A.At(r, r)-1.5)
			}
		}
		for r := range n {
			if rng.IntN(3) == 0 {
				for c := range m {
					B.Set(r, c, 0)
				}
			}
			if rng.IntN(3) == 0 {
				for c := range p {
					C.Set(c, r, 0)
				}
			}
		}
	}
	if rng.IntN(4) == 0 {
		for r := range p {
			for c := range m {
				D.Set(r, c, rng.NormFloat64())
			}
		}
	}
	tag := fmt.Sprintf("k%d n%d m%d p%d dt%g", kind, n, m, p, dt)
	if rng.IntN(7) == 0 {
		E := mat.NewDense(n, n, nil)
		for r := range n {
			for c := range n {
				v := 0.2 * rng.NormFloat64()
				if r == c {
					v++
				}
				E.Set(r, c, v)
			}
		}
		if ds, err := NewDescriptor(A, B, C, D, E, dt); err == nil {
			return ds, "desc " + tag
		}
	}
	sys, err := New(A, B, C, D, dt)
	if err != nil {
		return nil, "new"
	}
	return sys, tag
}
