```go
func rv4Rot(rng *rand.Rand, n int, s float64) (*mat.Dense, *mat.Dense, bool) {
	T := mat.NewDense(n, n, nil)
	for r := range n {
		for c := range n {
			v := s * rng.NormFloat64()
			if r == c {
				v++
			}
			T.Set(r, c, v)
		}
	}
	var Ti mat.Dense
	if Ti.Inverse(T) != nil {
		return nil, nil, false
	}
	return T, &Ti, true
}
func rv4Sim(T, X, Ti *mat.Dense) *mat.Dense {
	var t, o mat.Dense
	t.Mul(T, X)
	o.Mul(&t, Ti)
	return &o
}
