package controlsys

// Wave-42 review sweep (IR5YOF). Generators:
//   ctrl:   near-singular E (sigma_min = c*eps*10^u, u in [0,5]), generic
//           (rotated) or triangular, random Q >= 0, R > 0, n 2..6, m 1..3.
//   unc:    block-triangular plant whose near-infinite mode a22/e22 is
//           exactly uncontrollable (B last row 0) or nearly (delta), then
//           rotated A'=UAV, E'=UEV, B'=UB.
//   reg:    E = I or well-conditioned E with an uncontrollable mode on,
//           near or beyond the boundary, rotated.
// Discrete rows: Dare (descriptor X) and Dlqr; continuous: Care and Lqr.
// Oracles: 320-bit doubling on the explicit model (discrete) and 320-bit
// Newton from the returned K (both domains), with 1-ulp spread.
// ZRW_OUT output jsonl, ZRW_SEEDS per generator/domain.

import (
	"encoding/json"
	"errors"
	"math"
	"math/big"
	"math/cmplx"
	"math/rand/v2"
	"os"
	"strconv"
	"sync"
	"testing"

	"plantcontrol.org/v1/gonum/mat"
)

type zrwRow struct {
	Gen    string  `json:"gen"`
	Seed   uint64  `json:"seed"`
	Dt     float64 `json:"dt"`
	API    string  `json:"api"`
	N      int     `json:"n"`
	Verd   bool    `json:"verd"`
	Err    string  `json:"err,omitempty"`
	Bnd    bool    `json:"bnd"`
	Acc    int     `json:"acc"`
	EX     float64 `json:"ex"`
	EK     float64 `json:"ek"`
	SX     float64 `json:"sx"`
	SK     float64 `json:"sk"`
	Conv   bool    `json:"conv"`
	Robust bool    `json:"robust"`
	DX     float64 `json:"dx"`
	DK     float64 `json:"dk"`
	DOK    bool    `json:"dok"`
	DRho   float64 `json:"drho"`
	CondE  float64 `json:"conde"`
	Delta  float64 `json:"delta"`
	CL     float64 `json:"cl"`
	CLOK   bool    `json:"clok"`
}

func zrwOrth(rng *rand.Rand, n int) *mat.Dense {
	g := mat.NewDense(n, n, nil)
	for i := range n {
		for j := range n {
			g.Set(i, j, rng.NormFloat64())
		}
	}
	var qr mat.QR
	qr.Factorize(g)
	var q mat.Dense
	qr.QTo(&q)
	return &q
}

func zrwSPD(rng *rand.Rand, n int, psd bool) *mat.Dense {
	g := mat.NewDense(n, n, nil)
	for i := range n {
		for j := range n {
			g.Set(i, j, rng.NormFloat64())
		}
	}
	var q mat.Dense
	q.Mul(g, g.T())
	if !psd {
		for i := range n {
			q.Set(i, i, q.At(i, i)+0.5)
		}
	} else {
		for i := range n {
			q.Set(i, i, q.At(i, i)+1e-3)
		}
	}
	for i := range n {
		for j := i + 1; j < n; j++ {
			v := 0.5 * (q.At(i, j) + q.At(j, i))
			q.Set(i, j, v)
			q.Set(j, i, v)
		}
	}
	return &q
}

type zrwCase struct {
	A, B, E, Q, R *mat.Dense
	delta         float64
}

func zrwGen(gen string, seed uint64, dt float64) zrwCase {
	rng := rand.New(rand.NewPCG(seed, 42420+uint64(len(gen))))
	n := 2 + rng.IntN(5)
	m := 1 + rng.IntN(3)
	if rng.IntN(2) == 0 {
		m = 1
	}
	A, B, E := mat.NewDense(n, n, nil), mat.NewDense(n, m, nil), mat.NewDense(n, n, nil)
	for i := range n {
		for j := range n {
			A.Set(i, j, rng.NormFloat64())
		}
		for j := range m {
			B.Set(i, j, rng.NormFloat64())
		}
	}
	Q, R := zrwSPD(rng, n, true), zrwSPD(rng, m, false)
	if rng.IntN(2) == 0 {
		Q, R = eyeDense(n), eyeDense(m)
	}
	smin := (0.5 + 1.5*rng.Float64()) * eps() * math.Pow(10, 5*rng.Float64())
	var delta float64
	switch gen {
	case "ctrl":
		if rng.IntN(2) == 0 {
			for i := range n {
				E.Set(i, i, 0.5+rng.Float64())
				for j := i + 1; j < n; j++ {
					E.Set(i, j, rng.NormFloat64())
				}
			}
			E.Set(n-1, n-1, smin)
		} else {
			W := mat.NewDense(n, n, nil)
			for i := range n {
				W.Set(i, i, 0.5+rng.Float64())
			}
			W.Set(n-1, n-1, smin)
			var T mat.Dense
			T.Mul(zrwOrth(rng, n), W)
			E.Mul(&T, zrwOrth(rng, n))
		}
	case "unc", "reg", "big":
		for i := range n {
			E.Set(i, i, 0.5+rng.Float64())
			for j := i + 1; j < n; j++ {
				E.Set(i, j, rng.NormFloat64())
			}
		}
		for j := range n - 1 {
			A.Set(n-1, j, 0)
		}
		if gen == "unc" {
			E.Set(n-1, n-1, smin)
			a22 := 0.3 + rng.Float64()
			if rng.IntN(2) == 0 {
				a22 = -a22
			}
			A.Set(n-1, n-1, a22)
		} else if gen == "big" {
			if rng.IntN(3) == 0 {
				for i := range n {
					for j := range n {
						E.Set(i, j, 0)
					}
					E.Set(i, i, 1)
				}
			}
			lam := math.Pow(10, 1+9*rng.Float64())
			if rng.IntN(2) == 0 {
				lam = -lam
			}
			A.Set(n-1, n-1, lam*E.At(n-1, n-1))
		} else {
			if rng.IntN(3) == 0 {
				for i := range n {
					for j := range n {
						E.Set(i, j, 0)
					}
					E.Set(i, i, 1)
				}
			}
			var lam float64
			switch rng.IntN(4) {
			case 0:
				lam = 0
			case 1:
				lam = 1e-9 * rng.NormFloat64()
			case 2:
				lam = 0.5 + rng.Float64()
			default:
				lam = 1e-3 * rng.Float64()
			}
			if dt != 0 {
				s := 1.0
				if rng.IntN(2) == 0 {
					s = -1
				}
				lam = s * (1 + lam)
			}
			A.Set(n-1, n-1, lam*E.At(n-1, n-1))
		}
		switch rng.IntN(3) {
		case 0:
			delta = 0
		case 1:
			delta = math.Pow(10, -16+8*rng.Float64())
		default:
			delta = math.Pow(10, -8+6*rng.Float64())
		}
		for j := range m {
			B.Set(n-1, j, delta*rng.NormFloat64())
		}
		U, V := zrwOrth(rng, n), zrwOrth(rng, n)
		var t1, t2, t3 mat.Dense
		t1.Mul(U, A)
		t2.Mul(&t1, V)
		A = &t2
		t1.Reset()
		t1.Mul(U, E)
		t3.Mul(&t1, V)
		E = &t3
		var b2 mat.Dense
		b2.Mul(U, B)
		B = &b2
		var q2, q3 mat.Dense
		q2.Mul(V.T(), Q)
		q3.Mul(&q2, V)
		Q = &q3
		symmetrize(Q.RawMatrix().Data, n, n)
	}
	return zrwCase{mat.DenseCopyOf(A), mat.DenseCopyOf(B), mat.DenseCopyOf(E), mat.DenseCopyOf(Q), mat.DenseCopyOf(R), delta}
}

func zrwDoubling(a, b, h, r hbMat, steps int) (hbMat, bool) {
	n := a.r
	g := hbMul(b, hbSolve(r, b.t()))
	eye := newHbMat(n, n)
	for i := range n {
		eye.at(i, i).SetInt64(1)
	}
	tol := new(big.Float).SetPrec(hbPrec).SetFloat64(1e-80)
	for range steps {
		w := hbAdd(eye, hbMul(g, h), 1)
		wa, wg := hbSolve(w, a), hbSolve(w, g)
		hn := hbAdd(h, hbMul(hbMul(a.t(), h), wa), 1)
		g = hbAdd(g, hbMul(hbMul(a, wg), a.t()), 1)
		a = hbMul(a, wa)
		dm, hm := new(big.Float), new(big.Float)
		for i := range hn.d {
			d := new(big.Float).Sub(hn.d[i], h.d[i])
			if d.Abs(d).Cmp(dm) > 0 {
				dm = d
			}
			if v := new(big.Float).Abs(hn.d[i]); v.Cmp(hm) > 0 {
				hm = v
			}
		}
		h = hn
		if dm.Cmp(new(big.Float).Mul(hm, tol)) <= 0 {
			return h, true
		}
	}
	return h, false
}

func zrwDoublingOracle(A, B, Q, R, E *mat.Dense) (X, Y, K *mat.Dense, rho float64, ok bool) {
	e := hbFrom(E)
	a, b, r := hbSolve(e, hbFrom(A)), hbSolve(e, hbFrom(B)), hbFrom(R)
	y, conv := zrwDoubling(a, b, hbFrom(Q), r, 120)
	if !conv {
		return nil, nil, nil, 0, false
	}
	btx := hbMul(b.t(), y)
	k := hbSolve(hbAdd(r, hbMul(btx, b), 1), hbMul(btx, a))
	var ed mat.Eigen
	if !ed.Factorize(hbDense(hbAdd(a, hbMul(b, k), -1)), mat.EigenNone) {
		return nil, nil, nil, 0, false
	}
	for _, v := range ed.Values(nil) {
		rho = max(rho, cmplx.Abs(v))
	}
	z := hbSolve(e.t(), y)
	X = hbDense(hbSolve(e.t(), z.t()).t())
	symmetrize(X.RawMatrix().Data, X.RawMatrix().Rows, X.RawMatrix().Cols)
	return X, hbDense(y), hbDense(k), rho, rho < 1 && hbPositiveDefinite(y)
}

func zrwPerturb(rng *rand.Rand, a *mat.Dense) *mat.Dense {
	o := mat.DenseCopyOf(a)
	raw := o.RawMatrix()
	for i, v := range raw.Data {
		raw.Data[i] = v * (1 + (2*rng.Float64()-1)*eps())
	}
	return o
}

func zrwRun(gen string, seed uint64, dt float64, emit func(zrwRow)) {
	c := zrwGen(gen, seed, dt)
	n, _ := c.A.Dims()
	cont := dt == 0
	var lu mat.LU
	lu.Factorize(c.E)
	base := zrwRow{Gen: gen, Seed: seed, Dt: dt, N: n, CondE: lu.Cond(), Delta: c.delta}
	if pr, err := newRiccatiProblem(c.A, c.B, c.Q, c.R, &RiccatiOpts{E: c.E}); err == nil {
		base.Verd = pr.boundaryUnstabilizable(cont)
	}
	var dX, dY, dK *mat.Dense
	if !cont {
		dX, dY, dK, base.DRho, base.DOK = zrwDoublingOracle(c.A, c.B, c.Q, c.R, c.E)
	}
	apis := []string{"Dare", "Dlqr"}
	if cont {
		apis = []string{"Care", "Lqr"}
	}
	for _, api := range apis {
		r := base
		r.API = api
		gen := api == "Dare" || api == "Care"
		var res *RiccatiResult
		var err error
		opts := &RiccatiOpts{E: c.E}
		switch api {
		case "Dare":
			res, err = Dare(c.A, c.B, c.Q, c.R, opts)
		case "Dlqr":
			res, err = Dlqr(c.A, c.B, c.Q, c.R, opts)
		case "Care":
			res, err = Care(c.A, c.B, c.Q, c.R, opts)
		case "Lqr":
			res, err = Lqr(c.A, c.B, c.Q, c.R, opts)
		}
		if err != nil {
			r.Err = err.Error()
			r.Bnd = errors.Is(err, errBoundaryUnstabilizable)
			emit(r)
			continue
		}
		r.Acc = res.Accuracy
		r.CL, r.CLOK = zrwClosedLoop(cont, c.A, c.B, c.E, res.K)
		if r.DOK {
			want := dY
			if gen {
				want = dX
			}
			r.DX, r.DK = relErr(res.X, want), relErr(res.K, dK)
		}
		pick := func(Y, X *mat.Dense) *mat.Dense {
			if gen {
				return X
			}
			return Y
		}
		Y, X, Ko, ok := nearSingularOracle(cont, c.A, c.B, c.Q, c.R, nil, c.E, res.K)
		r.Conv = ok
		r.EX, r.EK = math.Inf(1), math.Inf(1)
		if ok {
			want := pick(Y, X)
			r.EX, r.EK = relErr(res.X, want), relErr(res.K, Ko)
			prng := rand.New(rand.NewPCG(7, 7))
			r.Robust = true
			for range 3 {
				Yp, Xp, Kp, okp := nearSingularOracle(cont, zrwPerturb(prng, c.A), zrwPerturb(prng, c.B), c.Q, c.R, nil, zrwPerturb(prng, c.E), Ko)
				if !okp {
					r.Robust = false
					continue
				}
				r.SX, r.SK = math.Max(r.SX, relErr(pick(Yp, Xp), want)), math.Max(r.SK, relErr(Kp, Ko))
			}
		}
		emit(r)
	}
}

func TestZZRW42Sweep(t *testing.T) {
	out := os.Getenv("ZRW_OUT")
	if out == "" {
		t.Skip("ZRW_OUT unset")
	}
	seeds := 300
	if s := os.Getenv("ZRW_SEEDS"); s != "" {
		seeds, _ = strconv.Atoi(s)
	}
	f, err := os.Create(out)
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()
	var mu sync.Mutex
	enc := json.NewEncoder(f)
	emit := func(r zrwRow) {
		mu.Lock()
		enc.Encode(r)
		mu.Unlock()
	}
	type job struct {
		gen  string
		seed uint64
		dt   float64
	}
	jobs := make(chan job)
	var wg sync.WaitGroup
	for range 3 {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for j := range jobs {
				zrwRun(j.gen, j.seed, j.dt, emit)
			}
		}()
	}
	for _, g := range []string{"ctrl", "unc", "reg", "big"} {
		for s := range seeds {
			for _, dt := range []float64{0, 1} {
				jobs <- job{g, uint64(s) + 10000, dt}
			}
		}
	}
	close(jobs)
	wg.Wait()
}

// zrwClosedLoop returns the spectral abscissa (continuous) or radius
// (discrete) of E⁻¹(A − BK) formed in 320 bits, and whether it is stable.
func zrwClosedLoop(cont bool, A, B, E, K *mat.Dense) (float64, bool) {
	e := hbFrom(E)
	a, b := hbSolve(e, hbFrom(A)), hbSolve(e, hbFrom(B))
	var ed mat.Eigen
	if !ed.Factorize(hbDense(hbAdd(a, hbMul(b, hbFrom(K)), -1)), mat.EigenNone) {
		return math.NaN(), false
	}
	v := math.Inf(-1)
	for _, l := range ed.Values(nil) {
		if cont {
			v = max(v, real(l))
		} else {
			v = max(v, cmplx.Abs(l))
		}
	}
	if cont {
		return v, v < 0
	}
	return v, v < 1
}
